"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[904],{908:(e,a,t)=>{t.d(a,{O:()=>n});let n=[{slug:"ai-small-business-marketing",title:"How AI Can Help Small Businesses Improve Their Marketing",category:"AI & Strategy",read:"6 min read",summary:"Practical ways to use AI to save time, sharpen your message, and make room for better decisions.",sections:[["Start with a task, not a tool","AI is most useful when you know the problem you want to solve. Choose one recurring task, such as turning a product explanation into a first draft of an email. Decide what a useful result looks like before choosing a tool. Start with a small workflow that you can review easily."],["Give it the context your customers need","Explain who you serve, what you sell, the problem it solves, and the tone you use. Include the action you want readers to take. Ask for a few distinct approaches instead of a long list of similar ideas. Remove any confidential customer or business information before sharing inputs."],["Turn one useful idea into several formats","A clear answer to a common customer question can become a short social post, a newsletter section, and an outline for a longer article. Ask AI to adapt the format while keeping the meaning consistent. Edit each version so it suits the channel and sounds like your business."],["Use AI for preparation, keep decisions human","AI can help organize customer questions, suggest research topics, and create a checklist for a campaign. It can also make mistakes or invent information. Verify factual claims against reliable sources, review any recommendations, and check that your final copy accurately describes your offer."],["Build a simple review habit","Before publishing, check accuracy, tone, privacy, and the next step. Ask whether a busy customer would understand the message. Measure the result that relates to your goal, such as qualified enquiries, rather than judging only by how much content you created."],["Your next step","Choose one repeatable task this week. Write a short brief, generate a draft, edit it carefully, and compare the effort and quality with your usual process. Keep the workflow only if it helps you create something useful. AI supports a clear strategy; it does not replace understanding your customers."]]},{slug:"prepare-facebook-instagram-ads",title:"What to Prepare Before Running Facebook and Instagram Ads",category:"Meta Ads",read:"7 min read",summary:"A clear offer, a useful landing page, and sensible measurement come before the launch button.",sections:[["Define one useful business objective","Decide what you want the campaign to help people do: make an enquiry, book a conversation, or purchase a specific product. Choose an objective your business can support and a way to assess the quality of the response. A campaign becomes easier to evaluate when its purpose is clear."],["Make your offer easy to explain","Write down who the offer is for, what problem it addresses, what is included, and what happens next. Check that any price, availability, or eligibility information is accurate. Ads cannot resolve confusion in the offer itself."],["Prepare the destination","Open your landing page on a phone. Does it match the promise in the ad? Is the next step obvious? Test the form, confirmation message, contact information, and page speed. Remove unnecessary fields and make sure someone is responsible for responding to enquiries."],["Check account access and measurement","Confirm the right people have access to your business and advertising assets. Review conversion tracking where appropriate and ensure any consent requirements are handled. Test important actions before using them to judge a campaign. Do not assume an installed tracking tool is measuring correctly."],["Plan a manageable test","Agree a budget you can afford to test, keep advertising spend separate from service fees, and decide what you want to learn. Prepare a few meaningful variations in the message or creative. Avoid changing everything at once, because it becomes harder to understand the findings."],["Prepare the follow-up","Write a helpful initial response and decide how quickly your team can reply. Keep a simple record of enquiry quality and common questions. Platform activity is only part of the picture; the customer experience after the click matters too."],["Before you launch","Review the offer, destination, access, tracking, creative, budget, and follow-up process together. Outcomes depend on your market, offer, budget, and execution. Use early findings to decide what to improve rather than treating the first campaign as a guaranteed source of sales."]]},{slug:"email-follow-ups-enquiries",title:"How Email Follow-Ups Help Turn Enquiries Into Customers",category:"Email Marketing",read:"6 min read",summary:"Stay helpful after the first enquiry with relevant messages, clear next steps, and permission.",sections:[["Understand why a conversation goes quiet","An unanswered enquiry does not always mean someone has lost interest. They may be comparing options, waiting for approval, or unsure what to do next. A thoughtful follow-up can answer an unresolved question and make the next step easier without adding pressure."],["Start with permission and expectations","Use an appropriate permission-based process for marketing messages. Tell people what they will receive and provide a clear way to unsubscribe. Keep enquiry responses relevant to the original request, and review applicable requirements before adding contacts to an ongoing marketing sequence."],["Make the first response useful","Acknowledge the question, provide the information you can, and explain the next step. Avoid asking for details you already have. If you need more context, ask one or two focused questions that help you respond properly."],["Give each follow-up a purpose","One message might clarify what the service includes. Another could answer a common question or explain how to prepare for a call. Avoid sending repeated reminders with no new value. Keep the message short and use one clear call to action."],["Automate carefully","Map the sequence before turning on automation. Choose reasonable timing and stop the sequence when someone replies, purchases, or unsubscribes, as appropriate. Test the links, personalization fallbacks, reply address, and unsubscribe flow with test contacts."],["Review quality as well as activity","Look at replies, relevant enquiries, and the next steps people take. Review delivery problems and unsubscribes too. An open alone does not tell you whether a person found the message useful. Use feedback to adjust timing, segmentation, and content."],["A practical starting point","Draft a helpful response to a common enquiry and one follow-up that answers a likely next question. Check consent, choose a relevant audience, and test the complete experience. Consistent follow-up can support decision-making, but it does not guarantee a purchase."]]}]},2904:(e,a,t)=>{t.d(a,{u2:()=>c,J0:()=>u});var n=t(5360);t(5139);var s=t(6708),o=t.n(s),i=t(9444),r=t(908);function u(e){let{secondary:a=!1}=e;return(0,n.jsxs)(o(),{className:a?"button secondary":"button",href:i._P.booking||"/contact#consultation",children:["Book a Free Consultation Call ",(0,n.jsx)("span",{"aria-hidden":"true",children:"↗"})]})}function c(e){let{items:a=r.O}=e;return(0,n.jsx)("div",{className:"grid three",children:a.map((e,a)=>(0,n.jsxs)(o(),{className:"article-card",href:"/blog/"+e.slug,children:[(0,n.jsxs)("div",{className:"article-art art-"+a,"aria-hidden":"true",children:[(0,n.jsx)("span",{children:"Meta Ads"===e.category?"↗":"Email Marketing"===e.category?"✉":"✳"}),(0,n.jsx)("small",{children:"THE MARKETING NOTEBOOK"})]}),(0,n.jsxs)("div",{className:"article-content",children:[(0,n.jsxs)("p",{className:"small teal",children:[e.category," ",(0,n.jsxs)("span",{className:"muted",children:[" / ",e.read]})]}),(0,n.jsx)("h3",{children:e.title}),(0,n.jsx)("p",{children:e.summary}),(0,n.jsx)("span",{className:"text-link",children:"Read article ↗"})]})]},e.slug))})}},5139:(e,a,t)=>{Object.defineProperty(a,"__esModule",{value:!0}),!function(e,a){for(var t in a)Object.defineProperty(e,t,{enumerable:!0,get:a[t]})}(a,{default:function(){return u},getImageProps:function(){return r}});let n=t(8870),s=t(6725),o=t(9749),i=n._(t(1119));function r(e){let{props:a}=(0,s.getImgProps)(e,{defaultLoader:i.default,imgConf:{deviceSizes:[640,750,828,1080,1200,1920,2048,3840],imageSizes:[16,32,48,64,96,128,256,384],path:"/_next/image",loader:"default",dangerouslyAllowSVG:!1,unoptimized:!1}});for(let[e,t]of Object.entries(a))void 0===t&&delete a[e];return{props:a}}let u=o.Image},9444:(e,a,t)=>{t.d(a,{$p:()=>o,_P:()=>s});var n=t(1063);let s={name:"Sanjay Ranpal",brand:"Digital Sanjaya",email:"sanjayaar03@gmail.com",phone:"",social:[],portrait:"",booking:n.env.NEXT_PUBLIC_BOOKING_URL||"",url:n.env.NEXT_PUBLIC_SITE_URL||"http://localhost:3000"},o=[{slug:"meta-ads",name:"Meta Ads",icon:"↗",tag:"Reach the right people",benefit:"Make your Facebook and Instagram advertising more focused.",summary:"Connect your offer with relevant audiences, test what resonates, and understand where your advertising budget goes.",who:"Businesses with a clear offer that want to reach potential customers on Facebook and Instagram.",problems:["Your ads get attention but few useful enquiries.","You are unsure which audiences or messages to test.","You cannot clearly connect advertising activity with business goals."],includes:["Audience and offer research","Campaign planning and account review","Ad copy and creative direction","Conversion tracking where appropriate","Retargeting where permitted and relevant","Structured testing and clear reporting"],process:["Review your offer, audience, budget, and tracking.","Agree campaign objectives, creative direction, and measurement.","Launch approved ads and monitor delivery.","Review findings and refine the next round of tests."],faq:[["Is advertising spend included?","Advertising spend is separate from service fees and is paid to the advertising platform. We agree a budget and scope before starting."],["Can you guarantee sales?","No. Performance depends on your offer, website, budget, market, and other factors. We set realistic goals and use evidence to guide improvements."],["Do I need existing ad accounts?","We can review what you already have and identify the account access, business assets, and tracking needed before launch."]]},{slug:"digital-marketing",name:"Digital Marketing",icon:"◎",tag:"Find your direction",benefit:"A practical marketing plan that fits your business.",summary:"Replace scattered activity with a clear direction for your message, channels, and next steps.",who:"Business owners who want a focused plan and a clearer understanding of where to spend their time and budget.",problems:["You are posting regularly without a clear purpose.","There are too many channels and too little time.","Your message does not make your offer easy to understand."],includes:["Marketing audit and opportunity review","Customer and competitor research","Positioning and messaging direction","Channel selection and priorities","Content direction and a practical action plan","Performance measurement and review"],process:["Understand your business, customers, and current marketing.","Identify gaps and prioritize useful opportunities.","Build an agreed plan with clear responsibilities.","Review progress and adapt the plan as evidence develops."],faq:[["Will I need every marketing channel?","No. We prioritize channels that fit your customers, capacity, and goals. A focused plan is easier to execute and evaluate."],["Can you work with my existing marketing?","Yes. The starting point is understanding what you already do, what is useful, and where improvements may help."],["What will I receive?","The agreed scope can include an audit, messaging direction, channel priorities, content direction, and an actionable measurement plan."]]},{slug:"email-marketing",name:"Email Marketing",icon:"✉",tag:"Keep the conversation going",benefit:"Thoughtful follow-ups that help customers take the next step.",summary:"Nurture enquiries and stay useful to existing customers with relevant, permission-based email.",who:"Businesses with permission to email their contacts that want a more consistent approach to follow-up and repeat purchases.",problems:["Enquiries go quiet after the first conversation.","Your emails are inconsistent or too generic.","New subscribers do not know what to do next."],includes:["Email strategy and consent review","Welcome sequences","Lead nurturing and timely follow-ups","Audience segmentation","Re-engagement campaigns for eligible contacts","Reporting and ongoing improvements"],process:["Review consent, contact quality, and your customer journey.","Map relevant messages and useful next steps.","Write, approve, and test campaigns and automations.","Review engagement, delivery, and opportunities to improve."],faq:[["Can I use a purchased email list?","This service focuses on permission-based email. We use contacts with appropriate permission, clear unsubscribe options, and relevant messaging."],["Can emails run automatically?","Yes. Welcome and nurturing sequences can respond to agreed triggers. We test timing, content, and unsubscribe behavior before launch."],["Which platform should I use?","We review your existing tools and needs before recommending a setup. Any platform costs are discussed separately."]]}]}}]);